#include <iostream>
#include <string>

int main() {
    std::string user_input;
    std::getline(std::cin, user_input);

    size_t pos = user_input.find("at");
    if (pos != std::string::npos) {
        user_input.replace(pos, 2, "@");
    }

    size_t dot_pos = user_input.find("dot");
    while (dot_pos != std::string::npos) {
        user_input.replace(dot_pos, 3, ".");
        dot_pos = user_input.find("dot");
    }

    if (!user_input.empty() && user_input[0] == '.') {
        user_input = "dot" + user_input.substr(1);
    }

    if (!user_input.empty() && user_input[0] == '@') {
        size_t at_pos = user_input.find("at");
        if (at_pos != std::string::npos) {
            user_input.replace(at_pos, 2, "@");
        }
        user_input = "at" + user_input.substr(1);
    }

    if (!user_input.empty() && user_input.back() == '.') {
        user_input.back() = 'd';
        user_input += "ot";
    }

    std::cout << user_input << std::endl;
    return 0;
}
